"""Deterministic source-contract retrieval and evidence-bearing request bindings."""
from copy import deepcopy
import re

from baseline_closure import BM25
from baseline_nlp import ntoks
from .context import context_spans, dates_in
from .engine import Engine
from .grounding import references
from .project import text
from .state import U


STOP = set('the a an with without and or for of to from on in by this that their they first new one '
           'controller service api http org springframework request response java string'.split())
# Language-level synonyms only; project entities, routes and enum values come from source.
VERBS = [set('get find query lookup search read view open show list refresh inspect fetch'.split()),
         set('create add insert register save book reserve'.split()),
         set('delete remove erase'.split()), set('update modify change edit'.split()),
         set('login signin authenticate'.split())]
VERBS[0].update(('check', 'browse', 'look'))


def tokens(value):
    words = ntoks(re.sub(r'\blog\s+in\b', 'login', str(value), flags=re.I))
    output = [word for word in words if word not in STOP]
    output += ['prefix' + word[:6] for word in output if len(word) >= 7]
    return output


def intent(value):
    value = re.sub(r'^as\b.*?,\s*|^(?:try\s+to|please)\s+', '', value, flags=re.I)
    words = tokens(value)
    return next((i for i, group in enumerate(VERBS) if words and words[0] in group), None)


def normalized(value):
    return re.sub(r'[^a-z0-9]', '', value.lower())


def absent_field(raw, key):
    words = re.findall(r'[a-z0-9]+', re.sub(r'([a-z0-9])([A-Z])', r'\1 \2', key).lower())
    if not words:
        return None
    pattern = r'\b(?:no|without)\s+' + r'[ _-]*'.join(map(re.escape, words)) + r'\b'
    for source, value in raw.items() if isinstance(raw, dict) else []:
        found = re.search(pattern, str(value), re.I)
        if found:
            return str(source), found[0]
    return None


def read_static_context(raw):
    spans, limited, credentials = context_spans(raw)
    facts = {}
    clock = None
    for pair in credentials:
        for name, ref in pair.items():
            span = spans[ref]
            facts[name] = {**span, 'kind': 'credential', 'reference': ref}
    for ref, span in spans.items():
        if span['type'] != 'date':
            continue
        label = span.get('label', '')
        if re.search(r'\b(?:system\s+clock|current\s+(?:date|time)|today)\b', label, re.I):
            clock = dates_in(str(span['value']))[0]
        else:
            facts.setdefault('request_date', {**span, 'kind': 'default', 'reference': ref})
    for key, value in raw.items() if isinstance(raw, dict) else []:
        if isinstance(value, (bool, int, float)) or (isinstance(value, str) and len(value.split()) == 1):
            facts[str(key)] = {'value': value, 'kind': 'default', 'quote': str(value), 'source': str(key)}
    unresolved = ['System clock is unknown'] if clock is None else []
    if limited:
        unresolved.append('Context span budget exceeded')
    return {'facts': facts, 'clock': clock, 'unresolved': unresolved, 'raw': deepcopy(raw)}


class ContractIndex:
    def __init__(self, project, frontend):
        self.project, self.frontend = project, frontend
        self.contracts, docs, extra_docs = {}, {}, {}
        for mid, verb, route in project.ix.handlers:
            sites = [s for s in frontend.sites.values() if mid in s['handlers']] or [None]
            for site in sites:
                key = mid + '|' + (site['id'] if site else '')
                name = project.methods[mid]['name']
                owner = project.nodes[project.methods[mid]['owner']]['fqn'].split('.')[-1]
                primary = tokens(name + ' ' + owner + ' ' + ' '.join(route)
                                 + ' ' + (site.get('action_label', '') if site else ''))
                source = text(project.ast.get(mid))[:1800]
                ui = (site['source'][:1000] + ' ' + site['file']) if site else ''
                docs[key] = primary + tokens(' '.join(project.request_fields(mid)))
                extra_docs[key] = tokens(source) + tokens(ui)
                self.contracts[key] = {'entry': mid, 'site': site, 'verb': verb,
                                       'route': route, 'primary': primary,
                                       'intent': intent(site.get('action_label', '')) if site and intent(site.get('action_label', '')) is not None else intent(name)}
        self.bm25 = BM25(docs)
        self.extra = BM25(extra_docs)

    def rank(self, action):
        # Weight the direct object before qualifications about related entities.
        focus = re.split(r'\b(?:for|with|without|from|departing|filtered|on|onto)\b', action, 1, flags=re.I)[0]
        query = tokens(focus)
        wanted = intent(action)
        verb_words = {word for group in VERBS for word in group}
        objects = [word for word in query if word not in verb_words]
        base = dict((key, score) for score, key in self.bm25.rank(query))
        extra = dict((key, score) for score, key in self.extra.rank(tokens(action)))
        result = []
        for key in set(base) | set(extra):
            contract = self.contracts[key]
            score = base.get(key, 0) + 0.15 * extra.get(key, 0)
            primary = set(contract['primary'])
            score += 2 * sum(self.bm25.idf.get(word, 0) for word in objects if word in primary)
            actual = contract['intent']
            if wanted is not None:
                score *= 1.8 if actual == wanted else 0.12 if actual is not None else 0.6
            elif query:
                score *= 2 if query[0] in primary else 0.35
            result.append((score, key, contract))
        return sorted(result, key=lambda item: (-item[0], item[1]))

    def candidates(self, action, limit=6):
        return list(dict.fromkeys(c['entry'] for _, _, c in self.rank(action)))[:limit]


def explicit_value(action, key, typ):
    words = re.findall(r'[a-z0-9]+', re.sub(r'([a-z0-9])([A-Z])', r'\1 \2', key).lower())
    label = r'[ _-]*'.join(re.escape(word) for word in words)
    # Match field labels, never positional bare numbers that could be dates or ordinals.
    patterns = [r'\b' + re.escape(key) + r'\b\s*(?:is|=|:)?\s*[\"\']([^\"\']+)[\"\']',
                r'\b' + label + r'\b\s*(?:is|=|:)?\s*([\w@.+-]+)'] if label else []
    for pattern in patterns:
        match = re.search(pattern, action, re.I)
        if match and match[1].lower() not in {'and', 'or', 'with', 'of', 'for', 'to', 'from'}:
            value = Engine.coerce(match[1], typ)
            if typ.split('.')[-1] in ('String', 'UUID') or value is not U:
                return value, match[0]
    if typ.split('.')[-1] in ('boolean', 'Boolean'):
        field = r'\b' + label + r'\b'
        for match in re.finditer(field, action, re.I):
            before = action[max(0, match.start() - 24):match.start()]
            if re.search(r'\b(?:without|no|not|disable)\s*$', before, re.I):
                return False, before + match[0]
            after = action[match.end():match.end() + 16]
            if re.match(r'\s*(?:is\s+)?(?:false|disabled)\b', after, re.I):
                return False, match[0] + after
            if re.search(r'\b(?:with|enable)\s*$', before, re.I) or re.match(r'\s*(?:is\s+)?(?:true|enabled)\b', after, re.I):
                return True, before + match[0] + after
    return U, ''


class ContractGrounder:
    def __init__(self, project, frontend, retrieval, parser, context):
        self.project, self.frontend, self.index, self.context = project, frontend, retrieval, context

    def step(self, action, state, scenario_text='', prepared_proposal=None):
        ranked = self.index.rank(action)
        candidates = [c['entry'] for _, _, c in ranked[:6]]
        detail = {'candidates': candidates, 'ranking': [
            {'entry': c['entry'], 'ui_site': c['site']['id'] if c['site'] else None, 'score': score}
            for score, _, c in ranked[:6]], 'proposal': {'hypotheses': []}, 'unresolved': []}
        detail['grounding_status'] = 'lexical_hypothesis'
        detail['certainty_note'] = 'Graph certainty is conditional on the selected source contract and validated bindings'
        if not ranked:
            detail['unresolved'] = ['No lexical evidence for a source request']
            return [], detail
        score, _, contract = ranked[0]
        mid, site = contract['entry'], contract['site']
        path_state = deepcopy(state)
        fields = self.project.request_fields(mid)
        params, bindings = {}, {}

        def bind(key, value, source, reference, quote=''):
            if value is not U:
                params[key] = Engine.coerce(deepcopy(value), fields[key])
                bindings[key] = {'source': source, 'reference': reference, 'quote': quote,
                                 'resolved': params[key] is not U}

        if site:
            self.frontend.enter(site, path_state)
            for key, expression in site['body_fields'].items():
                if key in fields:
                    bind(key, self.frontend.evaluate(expression, path_state, definitions=site['definitions']),
                         'ui', site['id'] + ':' + expression)
            url = self.frontend.evaluate(site['url'], path_state, definitions=site['definitions'])
            if isinstance(url, str):
                for key, value in Engine(self.project, path_state).path_parameters(mid, url).items():
                    if key in fields:
                        bind(key, value, 'ui', site['id'] + ':url')
        for key, typ in fields.items():
            value, quote = explicit_value(action, key, typ)
            if value is not U:
                bind(key, value, 'literal', 'action', quote)
                continue
            absence = absent_field(self.context.get('raw', {}), key)
            if absence and typ.split('.')[-1] in ('String', 'boolean', 'Boolean'):
                bind(key, '' if typ.split('.')[-1] == 'String' else False,
                     'context', absence[0], absence[1])
                continue
            for name, fact in self.context['facts'].items():
                if normalized(name) == normalized(key):
                    if fact['kind'] == 'credential' and re.search(r'\bnew\b', action, re.I):
                        if intent(action) == 1:
                            bind(key, path_state.fresh_input(key, typ), 'fresh', 'action', action)
                        else:
                            # Explicit new credentials cannot refer to the pre-existing account.
                            for i in range(len(state.history) - 1, -1, -1):
                                history_refs = references(state.history[i]['result'], 'history[' + str(i) + '].result')
                                matching = [(ref, val) for ref, val in history_refs.items()
                                            if normalized(ref.rsplit('.', 1)[-1]) == normalized(key) and val is not U]
                                if len(matching) == 1:
                                    bind(key, matching[0][1], 'history', matching[0][0])
                                    break
                        continue
                    bind(key, fact['value'], 'context', name, fact.get('quote', ''))
            if key in params:
                continue
            date_fields = [name for name in fields if set(tokens(name)) & {'date', 'time'}]
            if len(date_fields) == 1 and key in date_fields:
                dates = dates_in(action)
                if dates:
                    exact = next(m[0] for m in re.finditer(r'\b\d{4}-\d\d-\d\d(?:[ T]\d\d:\d\d(?::\d\d)?)?|\b\d{1,2}\s+[A-Za-z]+\s+\d{4}\b', action)
                                 if dates_in(m[0]))
                    bind(key, dates[0].isoformat(), 'literal', 'action', exact)
                elif 'request_date' in self.context['facts']:
                    bind(key, self.context['facts']['request_date']['value'], 'context', 'request_date')
            target = self.project.resolve_type(typ, self.project.methods[mid]['module'])
            enum = self.project.enum_members.get(target, [])
            matches = [e for e in enum if set(tokens(e.rsplit('.', 1)[-1])) <= set(tokens(action))]
            if len(matches) == 1:
                bind(key, self.project.enum_objects.get(matches[0], U), 'code', matches[0])
            # UI options keep the association to their actual form field.
            if site and key in site['body_fields']:
                expression = site['body_fields'][key]
                options = [o for o in site['options'] if o['control'] and o['control'] in expression
                           and set(tokens(o['label'])) and set(tokens(o['label'])) <= set(tokens(action))]
                if len(options) == 1:
                    bind(key, options[0]['value'], 'ui', site['id'] + ':option', options[0]['label'])
            if key in params:
                continue
            for i in range(len(state.history) - 1, -1, -1):
                refs = references(state.history[i]['result'], 'history[' + str(i) + '].result')
                matches = [(ref, value) for ref, value in refs.items()
                           if normalized(ref.rsplit('.', 1)[-1]) == normalized(key) and value is not U]
                if len(matches) == 1:
                    bind(key, matches[0][1], 'history', matches[0][0])
                    break
        problems = ['Unknown input: ' + key for key, typ in fields.items()
                    if key not in params and 'Header' not in typ]
        return [{'entry': mid, 'site': site, 'state': path_state, 'params': params, 'bindings': bindings,
                 'reason': 'Highest BM25 source/UI contract score: ' + str(score), 'unresolved': problems}], detail

"""Static extraction and symbolic evaluation of browser request contracts."""
from copy import deepcopy
from html.parser import HTMLParser
from pathlib import Path
import json
import re
from urllib.parse import urlsplit, parse_qsl
from tree_sitter import Language, Parser
import tree_sitter_javascript
from baseline_nlp import front_files, prefix_match
from baseline_closure import path_segs
from .project import text, walk
from .state import U


def pairs(node):
    return {text(c.child_by_field_name('key')).strip('\"\''): c.child_by_field_name('value')
            for c in node.named_children if c.type == 'pair'} if node and node.type == 'object' else {}


def literal(node):
    if node is None:
        return U
    raw = text(node)
    if node.type == 'string':
        try:
            return json.loads(raw) if raw.startswith('"') else raw[1:-1]
        except ValueError:
            return U
    try:
        return json.loads(raw)
    except ValueError:
        return U


def ancestor(node, kinds):
    while node and node.type not in kinds:
        node = node.parent
    return node


def unwrapped(node):
    while node is not None and node.type in ('expression_statement', 'parenthesized_expression'):
        node = node.named_children[0] if node.named_children else None
    return node


FUNCTIONS = ('function_expression', 'function_declaration', 'method_definition', 'arrow_function')


def substitute(expression, bindings):
    """Substitute reference identifiers, preserving string literals and property names."""
    parser = Parser(Language(tree_sitter_javascript.language()))
    source = ('(' + expression + ');').encode()
    tree = parser.parse(source)
    changes = []
    for node in walk(tree.root_node):
        if node.type == 'identifier' and text(node) in bindings:
            changes.append((node.start_byte, node.end_byte, '(' + bindings[text(node)] + ')'))
    for start, end, value in reversed(changes):
        source = source[:start] + value.encode() + source[end:]
    return source.decode()[1:-2]


def request_contexts(root, call, depth=0, visited=()):
    """Inline only direct, same-file named wrappers; no JavaScript is executed."""
    scope = ancestor(call.parent, (*FUNCTIONS, 'program'))
    name = text(scope.child_by_field_name('name'))
    pars = scope.child_by_field_name('parameters')
    parameters = [text(n) for n in pars.named_children] if pars else []
    if not name or not parameters:
        return [(scope, {})]
    if depth >= 3 or name in visited:
        return []
    contexts = []
    for caller in walk(root):
        if caller.type != 'call_expression' or text(caller.child_by_field_name('function')) != name:
            continue
        args = caller.child_by_field_name('arguments')
        values = args.named_children if args else []
        if len(values) != len(parameters):
            continue
        for outer, bindings in request_contexts(root, caller, depth + 1, (*visited, name)):
            contexts.append((outer, {key: substitute(text(value), bindings)
                                    for key, value in zip(parameters, values)}))
    return contexts or [(scope, {})]


class Page(HTMLParser):
    def __init__(self):
        super().__init__()
        self.values, self.labels, self.scripts, self.options = {}, [], [], []
        self.option = None
        self.select = ''

    def handle_starttag(self, tag, attrs):
        a = dict(attrs)
        if tag == 'script' and a.get('src'):
            self.scripts.append(a['src'])
        if tag == 'input' and a.get('id') and 'value' in a:
            self.values['#' + a['id']] = a['value']
        if tag == 'option' and 'value' in a:
            self.option = {'value': a['value'], 'label': '', 'control': self.select}
        if tag == 'select':
            self.select = a.get('id', a.get('name', a.get('v-model', '')))

    def handle_data(self, data):
        value = data.strip()
        if value:
            self.labels.append(value)
            if self.option is not None:
                self.option['label'] += value

    def handle_endtag(self, tag):
        if tag == 'option' and self.option is not None:
            self.options.append(self.option)
            self.option = None
        if tag == 'select':
            self.select = ''


class Frontend:
    def __init__(self, project):
        self.project = project
        self.parser = Parser(Language(tree_sitter_javascript.language()))
        self.sites, self.pages, self.trees, self.warnings = {}, {}, {}, []
        files = sorted(Path(p) for p in front_files(str(project.root)))
        for path in files:
            if path.suffix not in ('.html', '.htm'):
                continue
            page = Page()
            page.feed(path.read_text(errors='replace'))
            self.pages[path] = page
        for path in files:
            if path.suffix != '.js':
                continue
            source = path.read_bytes()
            tree = self.parser.parse(source)
            self.trees[path] = tree
            defaults = {}
            for node in walk(tree.root_node):
                if node.type == 'pair' and text(node.child_by_field_name('key')) == 'data':
                    defaults.update({k: literal(v) for k, v in pairs(node.child_by_field_name('value')).items()})
            pages = [(p, page) for p, page in self.pages.items()
                     if any((p.parent / src).resolve() == path.resolve() for src in page.scripts if not src.startswith(('http', '//')))]
            for call, caller_scope, argument_bindings in [
                    (c, scope, bindings) for c in walk(tree.root_node) if c.type == 'call_expression'
                    for scope, bindings in request_contexts(tree.root_node, c)]:
                if call.type != 'call_expression':
                    continue
                function = text(call.child_by_field_name('function'))
                args = call.child_by_field_name('arguments')
                if not args or not args.named_children:
                    continue
                config = pairs(args.named_children[0])
                if not config.get('url') or not re.search(r'ajax$|\$http$', function):
                    continue
                raw_url = substitute(text(config['url']), argument_bindings)
                local_definitions = {}
                for node in walk(caller_scope):
                    if node.type == 'variable_declarator':
                        local_definitions[text(node.child_by_field_name('name'))] = text(node.child_by_field_name('value'))
                # Resolve aliases only when their definition is a single expression.
                for _ in range(4):
                    changed = substitute(raw_url, {k: v for k, v in local_definitions.items()
                                                  if v and re.search(r'[\"\'](?:/|http)', v)})
                    if changed == raw_url:
                        break
                    raw_url = changed
                strings = re.findall(r'[\"\']([^\"\']+)[\"\']', raw_url)
                prefix = next((s for s in strings if s.startswith(('/', 'http'))), '')
                verb = str(literal(config.get('type') or config.get('method'))).upper()
                if not prefix:
                    self.warnings.append(str(path.relative_to(project.root)) + ': unresolved request URL')
                    continue
                segs = path_segs(urlsplit(prefix).path)
                handlers = sorted({mid for mid, hv, template in project.ix.handlers
                                   if (verb == str(U).upper() or hv is None or hv == verb)
                                   and ((len(segs) == len(template) and prefix_match(segs, template))
                                        or (len(segs) < len(template) and prefix_match(segs, template)))})
                if not handlers:
                    continue
                scope = ancestor(call.parent, (*FUNCTIONS, 'program'))
                definitions, fields = {}, {}
                for node in [*walk(caller_scope), *walk(scope)]:
                    if caller_scope == scope and node.start_byte >= call.start_byte:
                        continue
                    if node.type == 'variable_declarator':
                        definitions[text(node.child_by_field_name('name'))] = text(node.child_by_field_name('value'))
                    if node.type == 'assignment_expression':
                        lhs = text(node.child_by_field_name('left'))
                        if '.' in lhs:
                            owner, key = lhs.rsplit('.', 1)
                            fields.setdefault(owner, {})[key] = text(node.child_by_field_name('right'))
                data = substitute(text(config.get('data')), argument_bindings)
                seen, stringified = set(), False
                while data and data not in seen:
                    seen.add(data)
                    root = self.parser.parse(('(' + data + ');').encode()).root_node
                    node = unwrapped(root.named_children[0]) if root.named_children else None
                    if node is None:
                        break
                    if node.type == 'call_expression' and text(node.child_by_field_name('function')) == 'JSON.stringify':
                        args = node.child_by_field_name('arguments')
                        inner = unwrapped(args.named_children[0]) if args and len(args.named_children) == 1 else None
                        if inner is None:
                            break
                        data, stringified = text(inner), True
                        continue
                    raw = text(node)
                    if raw != data:
                        data = raw
                        continue
                    if node.type == 'identifier' and data in definitions and not (stringified and data in fields):
                        data = definitions[data]
                        continue
                    break
                body = fields.get(data, {})
                root = self.parser.parse(('(' + data + ');').encode()).root_node if data else None
                body_node = unwrapped(root.named_children[0]) if root and root.named_children else None
                if body_node is not None and body_node.type == 'object':
                    body = {key: text(value) for key, value in pairs(body_node).items()}
                elif config.get('data') is not None and not body and literal(body_node) is U:
                    self.warnings.append(str(path.relative_to(project.root)) + ': unresolved request body: ' + data[:160])
                for owner, properties in fields.items():
                    if definitions.get(owner) in ('new Object()', '{}'):
                        definitions[owner] = '{' + ','.join(json.dumps(k) + ':' + v for k, v in properties.items()) + '}'
                success = config.get('success')
                effects = []
                response_definitions = {}
                response_name = 'response'
                if success:
                    pars = success.child_by_field_name('parameters')
                    if pars and pars.named_children:
                        response_name = text(pars.named_children[0])
                    for node in walk(success):
                        if node.type == 'variable_declarator':
                            response_definitions[text(node.child_by_field_name('name'))] = text(node.child_by_field_name('value'))
                        condition = []
                        parent = node.parent
                        while parent and parent != success:
                            if parent.type == 'if_statement':
                                cond = text(parent.child_by_field_name('condition'))
                                alternative = parent.child_by_field_name('alternative')
                                condition.append('!(' + cond + ')' if alternative and alternative.start_byte <= node.start_byte < alternative.end_byte else cond)
                            parent = parent.parent
                        if node.type == 'call_expression':
                            fn = text(node.child_by_field_name('function'))
                            arguments = node.child_by_field_name('arguments')
                            values = arguments.named_children if arguments else []
                            storage = re.fullmatch(r'(?:sessionStorage|localStorage)\.setItem', fn)
                            dom = re.fullmatch(r'\$\(([\"\'])([^\"\']*)\1\)\.(val|text|html)', fn)
                            if storage and len(values) >= 2 and isinstance(literal(values[0]), str):
                                effects.append({'space': 'storage', 'key': literal(values[0]), 'expr': text(values[1]), 'conditions': condition})
                            elif dom and values:
                                effects.append({'space': 'dom', 'key': dom[2], 'expr': text(values[0]), 'conditions': condition})
                        elif node.type == 'assignment_expression':
                            lhs = text(node.child_by_field_name('left'))
                            if lhs.startswith(('this.', 'that.')):
                                effects.append({'space': 'form', 'key': lhs.split('.', 1)[1], 'expr': text(node.child_by_field_name('right')), 'conditions': condition})
                            elif lhs in ('location.href', 'window.location.href'):
                                effects.append({'space': 'navigation', 'key': 'href', 'expr': text(node.child_by_field_name('right')), 'conditions': condition})
                sid = path.relative_to(project.root).as_posix() + ':' + str(call.start_point.row + 1)
                if argument_bindings:
                    sid += '@' + str(caller_scope.start_point.row + 1) + ':' + str(len(self.sites))
                self.sites[sid] = {'id': sid, 'file': path.relative_to(project.root).as_posix(),
                                   'page': pages[0][0].relative_to(project.root).as_posix() if pages else path.relative_to(project.root).as_posix(),
                                   'line': call.start_point.row + 1, 'handlers': handlers, 'verb': verb,
                                   'url': raw_url, 'prefix': prefix, 'body_fields': body,
                                   'definitions': definitions, 'defaults': defaults,
